interface Clock {
  now(): Date;
}

function isExpired(placedAt: Date, clock: Clock, maxAgeMinutes: number): boolean {
  return clock.now().getTime() - placedAt.getTime() > maxAgeMinutes * 60_000;
}

class ManualClock implements Clock {
  constructor(private time: Date) {}
  now(): Date {
    return this.time;
  }
  advance(minutes: number): void {
    this.time = new Date(this.time.getTime() + minutes * 60_000);
  }
}

