};

function checkImports(all: Record<string, string>): string[] {
  const violations: string[] = [];
  for (const [file, source] of Object.entries(all)) {
    if (!/^src\/(domain|application)\//.test(file)) continue;
    for (const match of source.matchAll(/from\s+"([^"]+)"/g)) {
      if (match[1]!.includes("/adapters/")) violations.push(`${file} imports an adapter`);
    }
  }
  return violations;
}

