function lineByLine(initial: Record<string, number>): Stock {
  const stock = { ...initial };
  return {
    reserve(items) {
      for (const i of items) {
        if ((stock[i.sku] ?? 0) < i.qty) return false;
        stock[i.sku]! -= i.qty;
      }
      return true;
    },
    left: (sku) => stock[sku] ?? 0,
  };
}

function stockContract(name: string, make: (initial: Record<string, number>) => Stock): void {
  const stock = make({ "RICE-50KG": 5, "OIL-5L": 1 });
  const reserved = stock.reserve([{ sku: "RICE-50KG", qty: 2 }, { sku: "OIL-5L", qty: 3 }]);
  const untouched = !reserved && stock.left("RICE-50KG") === 5 && stock.left("OIL-5L") === 1;
  console.log(`${name}: ${untouched ? "ok" : "FAIL"}`);
}

stockContract("all-or-nothing", allOrNothing);
